package com.campus.registration.repository; import java.sql.*; public class Database{private final String url;public Database(String file){url="jdbc:sqlite:"+file;}public Connection connect()throws SQLException{return DriverManager.getConnection(url);}public void init()throws SQLException{try(var c=connect();var s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS students(id TEXT PRIMARY KEY,name TEXT,program TEXT,semester INTEGER)");s.executeUpdate("CREATE TABLE IF NOT EXISTS courses(code TEXT PRIMARY KEY,name TEXT,credits INTEGER,capacity INTEGER)");s.executeUpdate("CREATE TABLE IF NOT EXISTS prerequisites(course TEXT,prereq TEXT,PRIMARY KEY(course,prereq))");s.executeUpdate("CREATE TABLE IF NOT EXISTS sections(course TEXT,section TEXT,day TEXT,start INTEGER,end INTEGER,room TEXT,PRIMARY KEY(course,section))");s.executeUpdate("CREATE TABLE IF NOT EXISTS registrations(student TEXT,course TEXT,section TEXT,PRIMARY KEY(student,course))");s.executeUpdate("CREATE TABLE IF NOT EXISTS clash_logs(student TEXT,course TEXT,message TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP)");}}}